import catalogJson from '../../../data/catalog.json';

/**
 * Typed access to the shared catalog in data/catalog.json.
 * That file is generated by scripts/catalog-source.py and is also read by the
 * server (the AI shopping assistant uses it as product knowledge).
 */

export type ProductArtKind =
  | 'pack'
  | 'boot'
  | 'shell'
  | 'headlamp'
  | 'poles'
  | 'filter'
  | 'tent'
  | 'roll'
  | 'stove'
  | 'chair'
  | 'lantern'
  | 'bottle';

export interface Variant {
  sku: string;
  color: string;
  colorHex: string;
  size: string | null;
  stock: number;
}

export interface Product {
  id: string;
  name: string;
  category: string;
  price: number;
  tagline: string;
  description: string;
  features: string[];
  specs: { label: string; value: string }[];
  tags: string[];
  art: ProductArtKind;
  tone: string;
  image: string | null;
  variants: Variant[];
}

export interface Category {
  id: string;
  name: string;
}

interface Catalog {
  store: string;
  currency: string;
  categories: Category[];
  products: Product[];
}

const catalog = catalogJson as Catalog;

export const CATEGORIES: Category[] = catalog.categories;
export const PRODUCTS: Product[] = catalog.products;

const byId = new Map(PRODUCTS.map((p) => [p.id, p]));
const bySku = new Map(PRODUCTS.flatMap((p) => p.variants.map((v) => [v.sku, { product: p, variant: v }] as const)));

export const getProduct = (id: string | undefined) => (id ? byId.get(id) : undefined);
export const getBySku = (sku: string) => bySku.get(sku);
export const getCategoryName = (id: string) => CATEGORIES.find((c) => c.id === id)?.name ?? id;

/** Distinct colors in display order, with whether any size is in stock. */
export function colorsOf(product: Product) {
  const seen = new Map<string, { name: string; hex: string; inStock: boolean }>();
  for (const v of product.variants) {
    const existing = seen.get(v.color);
    if (existing) existing.inStock ||= v.stock > 0;
    else seen.set(v.color, { name: v.color, hex: v.colorHex, inStock: v.stock > 0 });
  }
  return [...seen.values()];
}

/** Distinct sizes in display order, or an empty array for one-size products. */
export function sizesOf(product: Product): string[] {
  return [...new Set(product.variants.map((v) => v.size).filter((s): s is string => s !== null))];
}

export function findVariant(product: Product, color: string, size: string | null) {
  return product.variants.find((v) => v.color === color && v.size === size);
}

export const isSoldOut = (product: Product) => product.variants.every((v) => v.stock === 0);

/** Related products: same category first, then shared tags. */
export function relatedTo(product: Product, limit = 4): Product[] {
  const score = (p: Product) =>
    (p.category === product.category ? 10 : 0) + p.tags.filter((t) => product.tags.includes(t)).length;
  return PRODUCTS.filter((p) => p.id !== product.id)
    .map((p) => ({ p, s: score(p) }))
    .filter(({ s }) => s > 0)
    .sort((a, b) => b.s - a.s)
    .slice(0, limit)
    .map(({ p }) => p);
}

/** One shipping rule for both checkouts, so the flag changes the experience, not the price. */
export const FREE_SHIPPING_MIN = 150;
export const FLAT_SHIPPING = 8;
export const shippingFor = (subtotal: number) => (subtotal >= FREE_SHIPPING_MIN ? 0 : FLAT_SHIPPING);

export const formatPrice = (value: number) =>
  new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(value);
